rule "uddi_normalize_dns_fields"
when
  has_field("event_class_id") && has_field("InfobloxDNSRCode")
then
  let rc = to_string($message.InfobloxDNSRCode);
  set_field("dns_event_type", "response");
  set_field("rcode", rc);
  set_field("qname", to_string($message.destinationDnsDomain));
  set_field("qtype", to_string($message.InfobloxDNSQType));
  set_field("dns_is_nxdomain", rc == "NXDOMAIN");
  set_field("dns_is_servfail", rc == "SERVFAIL");
  set_field("dns_is_error",    rc != "NOERROR" && rc != "");
end

rule "uddi_trim_unused_fields"
when
  has_field("event_class_id")
then
  // CEF answer/auth/additional counts — never queried
  remove_field("InfobloxAnCount");
  remove_field("InfobloxArCount");
  remove_field("InfobloxNsCount");
  // CSP B1 metadata — labels the customer/network/region, useful in CSP
  // not here
  remove_field("InfobloxB1ConnectionType");
  remove_field("InfobloxB1DHCPFingerprint");
  remove_field("InfobloxB1DNSTags");
  remove_field("InfobloxB1Network");
  remove_field("InfobloxB1OPHIPAddress");
  remove_field("InfobloxB1OPHName");
  remove_field("InfobloxB1Region");
  remove_field("InfobloxB1SrcOSVersion");
  // DNS flags/qclass — redundant with rcode
  remove_field("InfobloxDNSQFlags");
  remove_field("InfobloxDNSQClass");
  // Transport / app metadata — UDP/TCP only, low signal
  remove_field("applicationProtocol");
  remove_field("transportProtocol");
  remove_field("application_name");
  // Device metadata — constant per source (Infoblox NIOS-X strings)
  remove_field("deviceHostName");
  remove_field("device_vendor");
  remove_field("device_product");
  remove_field("device_version");
  remove_field("deviceAddress");
  // Redundant source-side IP/port (we use sender_ip/client_ip)
  remove_field("sourceMacAddress");
  remove_field("sourceAddress");
  remove_field("sourcePort");
  // Raw qname — already aliased to qname in stage 0
  remove_field("destinationDnsDomain");
  // event_* internals from CEF — high cardinality (event_uid), low value
  remove_field("event_log_name");
  remove_field("event_observer_hostname");
  remove_field("event_observer_id");
  remove_field("event_received_time");
  remove_field("event_repeat_count");
  remove_field("event_source_product");
  remove_field("event_start");
  remove_field("event_uid");
  remove_field("event_duration");
  // destination_* — UDDI ships these on DHCP/firewall event types but
  // no widget consumes them; cumulative they're a chunk of the field
  // explosion
  remove_field("destination_bytes_sent");
  remove_field("destination_packets_sent");
  remove_field("destination_zone");
  remove_field("destination_port");
  remove_field("destination_location_name");
  remove_field("destination_nat_ip");
  remove_field("destination_nat_port");
  remove_field("destination_nat_reserved_ip");
  remove_field("destination_reserved_ip");
  remove_field("destination_ip");
  remove_field("destination_fqdn");
end
